# F7-04/F7-05 phone layout: the existing 585-unit phone crop gets phone-sized chalk labels (x1.42), long notes wrap to two lines, short challenge footer.
EDITS=[("function tx(p,x,y,text,size=22,role='given'){return N.chalkText(p,x,y,String(text),{size,role});}\nfunction bx(p,x,y,w,h,role='given',text=null,size=21){return N.neonBox(p,x,y,w,h,{role,text,size,r:12});}", "const PHONE=()=>window.matchMedia('(max-width:720px)').matches;\nfunction tx(p,x,y,text,size=22,role='given'){if(PHONE()){size=Math.round(size*1.42);const t=String(text),room=560;if(t.length*size*.52>room){const fit=Math.floor(room/(t.length*.52));if(fit>=24)size=fit;else{const mid=t.lastIndexOf(' ',Math.ceil(t.length/2))>0?t.lastIndexOf(' ',Math.ceil(t.length/2)):t.indexOf(' ');if(mid>0){const a=t.slice(0,mid),b=t.slice(mid+1),s2=Math.min(size,Math.floor(room/(Math.max(a.length,b.length)*.52)));N.chalkText(p,x,y-s2,a,{size:s2,role});return N.chalkText(p,x,y,b,{size:s2,role});}size=Math.max(20,fit);}}}return N.chalkText(p,x,y,String(text),{size,role});}\nfunction bx(p,x,y,w,h,role='given',text=null,size=21){if(PHONE()&&text!=null)size=Math.min(Math.round(size*1.25),Math.floor(h*.62));return N.neonBox(p,x,y,w,h,{role,text,size,r:12});}"), ("tx(s,390,570,opt.challenge?'Drag a product card into the matching region.':", "tx(s,390,PHONE()?580:570,opt.challenge?(PHONE()?'Drag each card to its region.':'Drag a product card into the matching region.'):")]
